parameters.jsCode:
const body = $json.body || $json;
const event = body.event || body.webhook_event || body.event_name || '';
const message = body.message || body;
const conversation = body.conversation || message.conversation || body.conversation_meta || {};
const inbox = body.inbox || conversation.inbox || {};
const contact = body.contact || conversation.contact || message.sender || {};

const messageType = message.message_type;
const isIncoming = messageType === 'incoming' || messageType === 0 || messageType === '0';
const isPrivate = Boolean(message.private);
const content = String(message.content || body.content || '').trim();
const conversationId = conversation.id || body.conversation_id || message.conversation_id;
const messageId = message.id || body.message_id || body.id;
const inboxId = inbox.id || conversation.inbox_id || body.inbox_id;
const existingLabels = conversation.labels || body.labels || [];
const assigneeId = conversation.assignee_id || conversation.meta?.assignee?.id || null;

const ACCOUNT_ID = 1;
const WHATSAPP_INBOX_ID = 2;
const TEST_LABEL = 'testando-agente';
const AUTO_REPLY_LABEL = 'sdr-auto-responder';
const HUMAN_OFF_LABEL = 'agente-off';
const headers = body.headers || $json.headers || {};
const hasChatwootSignature = Boolean(headers['x-chatwoot-signature'] || headers['X-Chatwoot-Signature']) && Boolean(headers['x-chatwoot-timestamp'] || headers['X-Chatwoot-Timestamp']);

const isTestConversation = existingLabels.includes(TEST_LABEL);
const autoReplyEnabled = existingLabels.includes(AUTO_REPLY_LABEL);
const shouldSkip = !hasChatwootSignature || !isTestConversation || !conversationId || !messageId || !content || isPrivate || !isIncoming || Number(inboxId) !== WHATSAPP_INBOX_ID || existingLabels.includes(HUMAN_OFF_LABEL);

function includesAny(text, terms) {
  const t = text.toLowerCase();
  return terms.some(term => t.includes(term));
}
function cleanName(name) {
  const n = String(name || '').trim().split(' ')[0];
  return n && !/^\+?\d/.test(n) ? n : '';
}

const text = content.toLowerCase();
let produto = 'indefinido';
let memoria = 'memoria_geral_hk_nove';
let perfil = 'indefinido';
let score = 20;
const gatilhos = [];
const labelsAdd = ['sdr-hk-nove-v1'];
let resposta = '';
let handoffReason = '';

if (includesAny(text, ['multipropriedade', 'cota', 'semanas', 'interval', 'férias', 'ferias'])) {
  produto = 'multipropriedade_hilton'; memoria = 'memoria_multipropriedade_hilton'; perfil = 'ferias_multipropriedade'; score += 25;
  labelsAdd.push('produto-multipropriedade-hilton', 'perfil-temporada');
}
if (includesAny(text, ['lótus', 'lotus', 'sala comercial', 'sala', 'consultório', 'consultorio', 'escritório', 'escritorio'])) {
  produto = 'lotus_business'; memoria = 'memoria_lotus_business'; score += 25; labelsAdd.push('produto-lotus');
}
if (includesAny(text, ['centro médico', 'centro medico', 'medcenter', 'clínica', 'clinica', 'médico', 'medico', 'dentista'])) {
  produto = produto === 'indefinido' ? 'centro_medico_hilton' : produto; memoria = produto === 'centro_medico_hilton' ? 'memoria_centro_medico_hilton' : memoria;
  perfil = 'medico_clinica'; score += 20; labelsAdd.push('produto-centro-medico-hilton', 'perfil-saude');
}
if (includesAny(text, ['the spot', 'airbnb', 'temporada'])) {
  produto = 'the_spot_one'; memoria = 'memoria_the_spot_one'; perfil = perfil === 'indefinido' ? 'investidor' : perfil; score += 15; labelsAdd.push('produto-the-spot', 'perfil-investidor');
}
if (includesAny(text, ['hilton residencial', 'apartamento', 'pool', 'unidade residencial'])) {
  produto = produto === 'indefinido' ? 'hilton_residencial' : produto; memoria = produto === 'hilton_residencial' ? 'memoria_hilton_residencial' : memoria;
  score += 15; labelsAdd.push('produto-hilton-residencial');
}
if (produto === 'indefinido' && includesAny(text, ['hilton', 'hotel'])) {
  produto = 'hilton_indefinido'; memoria = 'memoria_hilton_geral'; score += 20; labelsAdd.push('produto-hilton');
}

if (includesAny(text, ['investir', 'investimento', 'investidor', 'renda', 'locação', 'locacao'])) { perfil = perfil === 'indefinido' ? 'investidor' : perfil; score += 15; labelsAdd.push('perfil-investidor'); }
if (includesAny(text, ['empresa', 'empresário', 'empresario', 'cnpj', 'sede'])) { perfil = 'empresario'; score += 15; labelsAdd.push('perfil-empresa'); }
if (includesAny(text, ['advogado', 'advocacia'])) { perfil = 'advogado'; score += 15; labelsAdd.push('perfil-advogado'); }
if (includesAny(text, ['corretor', 'parceria', 'parceiro'])) { perfil = 'corretor_parceiro'; labelsAdd.push('perfil-corretor-parceiro'); }

if (includesAny(text, ['tabela'])) { gatilhos.push('pediu_tabela'); labelsAdd.push('gatilho-pediu-tabela'); score += 30; }
if (includesAny(text, ['disponibilidade', 'disponível', 'disponivel'])) { gatilhos.push('pediu_disponibilidade'); labelsAdd.push('gatilho-pediu-disponibilidade'); score += 35; }
if (includesAny(text, ['valor', 'preço', 'preco', 'entrada', 'parcela', 'parcelamento'])) { gatilhos.push('perguntou_preco'); labelsAdd.push('gatilho-perguntou-preco'); score += 35; }
if (includesAny(text, ['proposta', 'simulação', 'simulacao'])) { gatilhos.push('pediu_proposta'); labelsAdd.push('gatilho-pediu-proposta'); score += 40; }
if (includesAny(text, ['reunião', 'reuniao', 'visita', 'agendar', 'agenda'])) { gatilhos.push('agendou_reuniao'); labelsAdd.push('gatilho-agendou-reuniao'); score += 50; }
if (includesAny(text, ['urgente', 'hoje', 'essa semana', 'fechar'])) { gatilhos.push('urgencia'); labelsAdd.push('gatilho-urgencia'); score += 25; }

score = Math.max(0, Math.min(100, score));
const temperatura = score >= 80 ? 'quente' : score >= 40 ? 'morno' : 'frio';
const assumirAlexandre = score >= 80 || gatilhos.length > 0;

let etapa = 'atendimento_inicial';
if (produto !== 'indefinido' || perfil !== 'indefinido') etapa = 'qualificacao';
if (produto !== 'indefinido' && produto !== 'hilton_indefinido') etapa = 'produto_direcionado';
if (gatilhos.includes('pediu_tabela') || gatilhos.includes('perguntou_preco') || gatilhos.includes('pediu_disponibilidade')) etapa = 'material_enviado';
if (gatilhos.includes('agendou_reuniao')) etapa = 'reuniao_visita_agendada';

const etapaLabelMap = {
  atendimento_inicial: 'etapa-atendimento-inicial', qualificacao: 'etapa-qualificacao', produto_direcionado: 'etapa-produto-direcionado', material_enviado: 'etapa-material-enviado', reuniao_visita_agendada: 'etapa-reuniao-visita'
};
labelsAdd.push(etapaLabelMap[etapa] || 'etapa-atendimento-inicial');
labelsAdd.push(`lead-${temperatura}`);
if (assumirAlexandre) labelsAdd.push('lead-prioridade-alexandre');
if (perfil === 'indefinido') labelsAdd.push('perfil-geral');
if (produto === 'indefinido') labelsAdd.push('produto-indefinido');

const nome = cleanName(contact.name || contact.pushname);
const saudacao = nome ? `Olá, ${nome}. Tudo bem?` : 'Olá, tudo bem?';

if (produto === 'lotus_business') {
  resposta = `${saudacao} Claro. O Lótus Business é um empreendimento comercial em Itapema, voltado para salas corporativas, profissionais liberais e investidores.\n\nVocê está buscando uma sala para uso próprio/empresa ou pensando mais como investimento?`;
} else if (produto === 'multipropriedade_hilton') {
  resposta = `${saudacao} Claro. A multipropriedade do Hilton é uma opção para quem quer usar o empreendimento em períodos definidos do ano, com uma proposta voltada a férias e uso planejado.\n\nVocê quer entender mais sobre como funcionam as semanas de uso ou sobre valores e disponibilidade?`;
} else if (produto === 'hilton_residencial') {
  resposta = `${saudacao} Claro. O Hilton Garden Inn Itapema tem opções residenciais voltadas para uso próprio e investimento, conforme regras e disponibilidade do empreendimento.\n\nVocê busca mais para investir ou para uso próprio em Itapema?`;
} else if (produto === 'centro_medico_hilton') {
  resposta = `${saudacao} Claro. O Centro Médico Hilton é voltado para profissionais da saúde, clínicas e consultórios em uma localização estratégica em Itapema.\n\nVocê atua na área da saúde ou está avaliando como investimento?`;
} else if (produto === 'the_spot_one') {
  resposta = `${saudacao} Claro. O The Spot One é um produto premium com forte apelo para investimento e uso em temporada, sempre conforme regras e disponibilidade.\n\nVocê está buscando mais renda com locação ou valorização patrimonial?`;
} else if (produto === 'hilton_indefinido') {
  resposta = `${saudacao} Claro, te ajudo com as informações do Hilton Garden Inn Itapema.\n\nVocê quer saber mais sobre unidade residencial, multipropriedade, investimento ou uso em temporada?`;
} else {
  resposta = `${saudacao} Claro, te ajudo. Para eu te enviar a informação certa, você quer saber sobre o Lótus Business, Hilton Garden Inn Itapema ou outro empreendimento?`;
}

if (assumirAlexandre) {
  handoffReason = gatilhos.join(', ') || 'lead quente';
  resposta += `\n\nJá vou deixar seu atendimento direcionado para o comercial confirmar os detalhes com a tabela vigente.`;
}

const removablePrefixes = ['etapa-', 'lead-frio', 'lead-morno', 'lead-quente', 'produto-', 'perfil-', 'gatilho-'];
const preservedLabels = existingLabels.filter(l => !removablePrefixes.some(p => l.startsWith(p)));
const finalLabels = [...new Set([...preservedLabels, ...labelsAdd])];

let skipReason = '';
if (!hasChatwootSignature) skipReason = 'sem assinatura/timestamp do Chatwoot';
else if (!isTestConversation) skipReason = 'conversa sem label testando-agente';
else if (!conversationId || !messageId) skipReason = 'payload sem conversation_id/message_id';
else if (!content) skipReason = 'mensagem vazia';
else if (isPrivate || !isIncoming) skipReason = 'mensagem não recebida do cliente';
else if (Number(inboxId) !== WHATSAPP_INBOX_ID) skipReason = `inbox inválido: ${inboxId}`;
else if (existingLabels.includes(HUMAN_OFF_LABEL)) skipReason = 'agente-off';

const resumo = shouldSkip ? `Evento ignorado pelo SDR HK Nove: ${skipReason}.` : `Produto: ${produto}; Memória: ${memoria}; Perfil: ${perfil}; Score: ${score}; Temperatura: ${temperatura}; Gatilhos: ${gatilhos.join(', ') || 'nenhum'}; Auto-resposta: ${autoReplyEnabled ? 'habilitada' : 'só sugestão'}.`;

return [{ json: {
  shouldSkip, event, account_id: ACCOUNT_ID, conversation_id: conversationId, message_id: messageId, inbox_id: inboxId,
  contact_id: contact.id || null, contact_name: contact.name || contact.pushname || '', contact_phone: contact.phone_number || contact.identifier || '',
  message_text: content, existing_labels: existingLabels, final_labels: finalLabels, assignee_id: assigneeId,
  sdr_mode: autoReplyEnabled ? 'auto_reply_test' : 'suggestion_only',
  shouldSendPublicReply: !shouldSkip && autoReplyEnabled,
  reply_text: resposta,
  classification: {
    agente: 'SDR HK Nove', produto_interesse: produto, memoria_consultada: memoria, perfil_lead: perfil, funil_etapa: etapa,
    lead_score: score, lead_temperatura: temperatura, gatilhos, assumir_alexandre: assumirAlexandre,
    motivo_handoff: handoffReason, proxima_acao: assumirAlexandre ? 'alexandre_assumir' : 'continuar_qualificacao',
    resumo_interno: resumo, resposta_sugerida: resposta, risco_compliance: false, observacoes_compliance: ''
  }
}}];

