parameters.jsCode:
const source = $('SDR HK Nove — Classificar + responder v1').first().json;
const tasks = $json.tasks || [];
const task = tasks.find(t => (t.conversation_ids || []).map(Number).includes(Number(source.conversation_id))) || tasks[0];

const stepMap = {
  novo_lead: 17,
  atendimento_inicial: 17,
  qualificacao: 18,
  produto_direcionado: 18,
  material_enviado: 18,
  reuniao_visita_agendada: 19,
  proposta_negociacao: 21,
  fechado: 22,
  perdido_nutricao: 24
};

const cls = source.classification;
let boardStepId = stepMap[cls.funil_etapa] || 17;
if ((cls.gatilhos || []).includes('pediu_proposta')) boardStepId = 20;
if ((cls.gatilhos || []).includes('agendou_reuniao')) boardStepId = 19;

const hermesBlock = [
  '---',
  `🤖 SDR HK Nove — ${new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })}`,
  `Produto: ${cls.produto_interesse}`,
  `Perfil: ${cls.perfil_lead}`,
  `Score: ${cls.lead_score} — ${cls.lead_temperatura}`,
  `Etapa Hermes: ${cls.funil_etapa}`,
  `Gatilhos: ${(cls.gatilhos || []).join(', ') || 'nenhum'}`,
  `Próxima ação: ${cls.proxima_acao}`,
  `Resumo: ${cls.resumo_interno}`
].join('
');

const customAttributes = {
  hermes_score: cls.lead_score,
  hermes_temperatura: cls.lead_temperatura,
  hermes_produto: cls.produto_interesse,
  hermes_perfil: cls.perfil_lead,
  hermes_etapa: cls.funil_etapa,
  hermes_proxima_acao: cls.proxima_acao
};

if (!task?.id) {
  const name = source.contact_name || source.contact_phone || 'Lead sem nome';
  return [{ json: {
    hasTask: false,
    action: 'create',
    board_id: 3,
    board_step_id: boardStepId,
    title: `Conversa #${source.conversation_id} - ${name}`,
    description: hermesBlock,
    custom_attributes: Object.assign({}, customAttributes, { hermes_origem: 'workflow_auto_create' }),
    conversation_ids: [Number(source.conversation_id)],
    conversation_id: source.conversation_id
  }}];
}

const originalDescription = task.description || '';
return [{ json: {
  hasTask: true,
  action: 'update',
  task_id: task.id,
  board_id: task.board_id || 3,
  board_step_id: boardStepId,
  current_step_id: task.board_step_id,
  title: task.title,
  description: originalDescription ? `${originalDescription}

${hermesBlock}` : hermesBlock,
  custom_attributes: Object.assign({}, task.custom_attributes || {}, customAttributes),
  conversation_id: source.conversation_id
}}];
